import { Component, OnInit } from '@angular/core';
import {HttpClient,HttpHeaders,HttpErrorResponse} from '@angular/common/http'
import {HomeService} from '../../home.service'
import {NavController} from '@ionic/angular'
import {ActivatedRoute,Router,ParamMap} from '@angular/router';
import { AlertController } from '@ionic/angular';
import { Observable, Subscriber } from 'rxjs';
@Component({
  selector: 'app-individualdisplay',
  templateUrl: './individualdisplay.page.html',
  styleUrls: ['./individualdisplay.page.scss'],
})
export class IndividualdisplayPage implements OnInit {
  details=[];
  public z1:string; public z2:string;public z3:string;

    constructor(private http:HttpClient,private user:HomeService,private route:ActivatedRoute,private navCtrl:NavController,private router:Router,private alertCtrl:AlertController)
    {
      this.route.paramMap.subscribe(
      params => {
      this.z1=params.get('a');
      this.z2=params.get('id');
      })
      }


  ngOnInit() {    
    this.user.individualdisplay(this.z1,this.z2).subscribe(data =>{
      this.details=data as any;
    })
  }

}
